module sample_stream_sink #(parameter DATA_WIDTH=32)(input clk,input rst_n,input valid,output ready,input [DATA_WIDTH-1:0] data,input [63:0] timestamp,input [7:0] channel_id,output reg [31:0] sample_count); reg [63:0] last_timestamp; assign ready=1'b1; always @(posedge clk or negedge rst_n) if(!rst_n) begin sample_count<=0;last_timestamp<=0; end else if(valid&&ready) begin if(sample_count!=0&&timestamp<last_timestamp)$error("sample timestamp decreased"); sample_count<=sample_count+1'b1;last_timestamp<=timestamp;$display("[SAMPLE] channel=%0d timestamp=%0d data=%h",channel_id,timestamp,data); end endmodule
